export function renderWorldProp(target={}){
 const name=kind[target.id]||'pin';
 return `<svg class="lux-prop lux-prop-${name}" viewBox="0 0 96 96" aria-hidden="true" focusable="false"><ellipse class="prop-shadow" cx="48" cy="86" rx="36" ry="7"/>${shapes[name]}</svg>`;
}
